import axios from 'axios';
export default { callAPI }



export async function callAPI(keyName, params) {

    // API Flash
    if (keyName === 'APIFLASH') {
        const API_key = process.env.REACT_APP_APIFLASH_KEY;

        const URL = params['URL'];
        const image_name = params['image_name'];

        axios.get("https://api.apiflash.com/v1/urltoimage", {
            params: {
                access_key: API_key,
                url: URL,
                fresh: 'true',
                full_page: 'true',
                quality: '100',
                crop: '420,0,1080,1080',
                time_zone: Intl.DateTimeFormat().resolvedOptions().timeZone
            },
            responseType: 'arraybuffer'
        }).then(response => {
            // fs.writeFile("metadata_files/" + image_name + ".png", response.data, "binary", error => {
            //     console.log(error);
            // });
            console.log("Image data from APIFLASH received.");
        }).catch(error => {
            console.log(error);
        });
    } else

    // Discord
    // WARNING: Making Discord API calls from the client-side exposes your bot token.
    // This is a major security risk. This code should be moved to a server-side environment.
    if (keyName === 'DISCORD') {
        
        const API_key = process.env.REACT_APP_DISCORD_BOT_TOKEN;
        console.log("API Key: ", API_key);
        
        const recipient_discord_ID = params['recipient_discord_ID'];
        var channel_discord_ID = params['channel_discord_ID'];
        const message = params['message'];
        
        const headers = {
            'Content-Type': 'application/json',
            'Authorization': `Bot ${API_key}`
        };

        // Direct Messages
        if (recipient_discord_ID) {
            axios.post('https://discord.com/api/v9/users/@me/channels', { recipient_id: recipient_discord_ID }, { headers })
                .then(response => {
                    console.log(response.data);
                    const channel_discord_ID = response.data.id;
                    console.log('Generated DM Channel ID: ', channel_discord_ID);
                    return axios.post(`https://discord.com/api/v9/channels/${channel_discord_ID}/messages`, { content: message }, { headers });
                })
                .then(response => {
                    console.log(response.data);
                })
                .catch(error => {
                    console.log(error);
                });
        
        // Channel Messages
        } else if (channel_discord_ID) {
            axios.post(`https://discord.com/api/v9/channels/${channel_discord_ID}/messages`, { content: message }, { headers })
                .then(response => {
                    console.log(response.data);
                })
                .catch(error => {
                    console.log(error);
                });
        }
    } else
    // 
    // DALL-E API
    if (keyName === 'DALLE') {
      const API_key = params['API_key'];
      const text = params['text'];

      axios.post("https://api.openai.com/v1/images/generations", {
          "model": "image-alpha-001",
          "prompt": `${text}`,
          "num_images": 1,
          "size": "256x256", // must be one of '256x256', '512x512', or '1024x1024'
          "response_format": "url"
        }, {
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${API_key}`
        }
      }).then(response => {
        const JSON_response = response.data;
        console.log("JSON Response: ", JSON_response);
        const image_URL = JSON_response.data[0]['url'];
        params['image_URL_element'].innerHTML = 'DALL-E Image URL: ' + image_URL;
        params['image_element'].src = image_URL;
        console.log("Image URL: ", image_URL);
        return(image_URL);
      }).catch(error => {
        console.log(error);
      });
  }
}

